#### `user/inodeReader.c`
```c
#include "kernel/types.h"
#include "kernel/fs.h"
#include "user/user.h"

int main(int argc, char *argv[]) {
    if(argc < 2) { printf("Usage: inodereader inum\n"); exit(1); }
    struct inode_info info;
    int inum = atoi(argv[1]);
    if(get_dinode(inum, &info) < 0) { printf("Error reading inode\n"); exit(1); }
    printf("Inode: %d\nType: %d\nSize: %d\nLinks: %d\nBlocks: ", inum, info.type, info.size, info.nlink);
    for(int i=0; i<13; i++) printf("%d ", info.addrs[i]);
    printf("\n");
    exit(0);
}
```

#### `user/directoryWalker.c`
```c
#include "kernel/types.h"
#include "kernel/fs.h"
#include "kernel/stat.h"
#include "user/user.h"

void walk(char *path) {
  int fd;
  struct dirent de;
  struct stat st;
  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) {
    close(fd);
    return;
  }
  while(read(fd, &de, sizeof(de)) == sizeof(de)) {
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0)
      continue;
    printf("%-14s %d\n", de.name, de.inum);
  }
  close(fd);
}

int main() {
  walk("/");
  exit(0);
}
```

